formData.jsFunction:
def validate(request, response = [:]) {
    if (request.containsKey("listOfFilesToBeDeleted")) {
        def filesListArray = request.listOfFilesToBeDeleted
        if (filesListArray.size() != 0) {
            filesListArray.each { eachObject ->
                if (!eachObject.containsKey("fileName")) {
                    response.message = "Please Provide Mandatory field: 'fileName'."
                }
            }
        } else {
            response.message = "Please select atleast one file to perform delete operation."
        }
    } else {
        response.message = "Please provide the file(s) to be deleted."
    }

    return response
}
